# =====================================================
# DATA HELPERS
# =====================================================
COMMON_FREQ = "15min"


def load_file_by_date(path, target_date):
    files = sorted(glob.glob(path))
    if not files:
        return None
    date_str = target_date.strftime("%Y%m%d")
    matching = [f for f in files if date_str in os.path.basename(f)]
    if not matching:
        return None
    try:
        return pd.read_excel(matching[-1])
    except Exception:
        try:
            return pd.read_csv(matching[-1])
        except Exception:
            return None


def normalize(df):
    df.columns = [str(c).strip().lower() for c in df.columns]
    t  = [c for c in df.columns if "time"   in c]
    dc = [c for c in df.columns if "dc"     in c]
    ac = [c for c in df.columns if "active" in c or "ac" in c]
    if not (t and dc and ac):
        return None, None, None, None
    t, dc, ac = t[0], dc[0], ac[0]
    df[t]  = pd.to_datetime(df[t],  errors="coerce")
    df[dc] = pd.to_numeric(df[dc],  errors="coerce")
    df[ac] = pd.to_numeric(df[ac],  errors="coerce")
    df = df.dropna(subset=[t, dc, ac]).sort_values(t)
    if df.empty:
        return None, None, None, None
    return df, t, dc, ac


def normalize_havells(df):
    df = df.copy()
    t_col = "Updated Time"
    if t_col not in df.columns:
        return None, None, None, None
    df["_time"] = pd.to_datetime(df[t_col], errors="coerce")
    dc_cols = [c for c in df.columns if c.startswith("DC Power PV") and c.endswith("(W)")]
    df["_dc_kw"] = (
        df[dc_cols].apply(pd.to_numeric, errors="coerce").sum(axis=1) / 1000.0
        if dc_cols else 0.0
    )
    ac_src = "Total AC Output Power (Active)(W)"
    if ac_src not in df.columns:
        return None, None, None, None
    df["_ac_kw"] = pd.to_numeric(df[ac_src], errors="coerce") / 1000.0
    df = df.dropna(subset=["_time", "_ac_kw"]).sort_values("_time")
    if df.empty:
        return None, None, None, None
    return df, "_time", "_dc_kw", "_ac_kw"


def compute_daily_energy_kwh(df, t, dc):
    if df is None or len(df) < 2:
        return 0.0
    times_h = (df[t] - df[t].iloc[0]).dt.total_seconds().values / 3600.0
    return max(float(_trapezoid(df[dc].values, x=times_h)), 0.0)


def resample_to_grid(df_raw, time_col="time", freq=COMMON_FREQ):
    df = df_raw.copy()
    df[time_col] = pd.to_datetime(df[time_col])
    df = df.set_index(time_col).sort_index()
    df = df.resample(freq).mean(numeric_only=True)
    return df.ffill(limit=2).fillna(0).reset_index()


def aggregate_plants(plant_dict, load_fn, norm_fn, current_date):
    valid_data    = {}
    device_frames = []
    daily_energy  = 0.0
    for name, path in plant_dict.items():
        raw = load_fn(path, current_date)
        if raw is None:
            continue
        df, t, dc, ac = norm_fn(raw)
        if df is None:
            continue
        valid_data[name] = (df, t, dc, ac)
        daily_energy    += compute_daily_energy_kwh(df, t, dc)
        frame = pd.DataFrame({"time": df[t], "dc": df[dc], "ac": df[ac]})
        device_frames.append(resample_to_grid(frame, "time"))
    df_agg = None
    if device_frames:
        df_agg = (
            pd.concat(device_frames)
              .groupby("time").sum()
              .reset_index()
              .sort_values("time")
        )
        df_agg = df_agg[(df_agg["dc"] + df_agg["ac"]) > 0.01]
    return df_agg, valid_data, daily_energy


def get_combined_data(current_date):
    """Single source of truth for all tabs including the map."""
    df_iso, valid_iso, iso_kwh = aggregate_plants(
        PLANTS,         load_file_by_date, normalize,         current_date)
    df_hav, valid_hav, hav_kwh = aggregate_plants(
        HAVELLS_PLANTS, load_file_by_date, normalize_havells, current_date)
    total_kwh = iso_kwh + hav_kwh

    parts = []
    if df_iso is not None and not df_iso.empty:
        parts.append(df_iso[["time","dc","ac"]].copy())
    if df_hav is not None and not df_hav.empty:
        parts.append(df_hav[["time","dc","ac"]].copy())

    df_total = None
    if parts:
        m = pd.concat(parts).groupby("time").sum().reset_index().sort_values("time")
        df_total = m[(m["dc"] + m["ac"]) > 0.01]

    return df_iso, df_hav, df_total, valid_iso, valid_hav, iso_kwh, hav_kwh, total_kwh


