def small_plot(df, t, dc, ac):
    fig = go.Figure()
    fig.add_trace(go.Scatter(
        x=df[t], y=df[dc], name="DC",
        line=dict(color=ORANGE, width=1.8),
        fill="tozeroy", fillcolor="rgba(255,107,0,0.08)",
        hovertemplate="<b>%{x|%H:%M}</b><br>DC <b>%{y:.1f} kW</b><extra></extra>"
    ))
    fig.add_trace(go.Scatter(
        x=df[t], y=df[ac], name="AC",
        line=dict(color=SKY, width=1.8),
        hovertemplate="<b>%{x|%H:%M}</b><br>AC <b>%{y:.1f} kW</b><extra></extra>"
    ))
    fig.update_layout(
        height=115, showlegend=False, hovermode="x unified",
        plot_bgcolor=BG_CARD, paper_bgcolor=BG_CARD,
        margin=dict(l=38, r=4, t=4, b=26),
        font=dict(color=BLUE_MUTED, family="Inter", size=9),
        xaxis=dict(**_axis_x, tickformat="%H"),
        yaxis=dict(**_axis_y),
        hoverlabel=_hover_layout
    )
    return fig


def large_chart(df_agg, height=380):
    fig = go.Figure()
    if df_agg is not None and not df_agg.empty:
        fig.add_trace(go.Scatter(
            x=df_agg["time"], y=df_agg["dc"], name="DC Power",
            line=dict(color=ORANGE, width=2.2),
            fill="tozeroy", fillcolor="rgba(255,107,0,0.07)",
            hovertemplate="<b>%{x|%H:%M}</b><br>DC <b>%{y:.1f} kW</b><extra></extra>"
        ))
        fig.add_trace(go.Scatter(
            x=df_agg["time"], y=df_agg["ac"], name="AC Power",
            line=dict(color=SKY, width=2.2),
            fill="tozeroy", fillcolor="rgba(14,165,233,0.05)",
            hovertemplate="<b>%{x|%H:%M}</b><br>AC <b>%{y:.1f} kW</b><extra></extra>"
        ))
        if len(df_agg["ac"]) > 0:
            pk = df_agg["ac"].max()
            pt = df_agg.loc[df_agg["ac"].idxmax(), "time"]
            fig.add_annotation(
                x=pt, y=pk, text=f"  Peak  {pk:.1f} kW",
                showarrow=True, arrowhead=2, arrowcolor=SKY,
                font=dict(color=BLUE_DARK, size=11, family="JetBrains Mono"),
                bgcolor=BG_CARD, bordercolor=SKY, borderwidth=1.5, borderpad=5
            )
    fig.update_layout(
        height=height, hovermode="x unified",
        plot_bgcolor=BG_CARD, paper_bgcolor=BG_CARD,
        margin=dict(l=62, r=14, t=22, b=48),
        font=dict(color=BLUE_MUTED, family="Inter", size=11),
        xaxis=dict(**_axis_x, title="Time of Day", tickformat="%H:%M"),
        yaxis=dict(**_axis_y, title="Power (kW)"),
        hoverlabel=_hover_layout,
        legend=dict(
            bgcolor=BG_CARD, bordercolor=BORDER, borderwidth=1,
            font=dict(color=BLUE_SLATE, size=11),
            orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1
        ),
    )
    return fig


def eco_cards(daily_kwh):
    co2  = (daily_kwh * CO2_PER_KWH)  / 1000
    coal = (daily_kwh * COAL_PER_KWH) / 1000
    tree =  daily_kwh * TREES_PER_KWH
    st.markdown('<hr class="divider">', unsafe_allow_html=True)
    st.markdown('<div class="eco-section-label">🌿 &nbsp;Daily Emission Reduction Estimate</div>',
                unsafe_allow_html=True)
    e1, e2, e3 = st.columns(3)
    with e1:
        st.markdown(f"""<div class="eco-card co2">
            <span class="eco-icon">💨</span>
            <div class="eco-label">CO₂ Reduced</div>
            <div class="eco-value">{co2:,.3f}<span class="eco-unit"> ton</span></div>
            <div class="eco-desc">{daily_kwh:,.0f} kWh × 0.997 kg/kWh</div>
            <div class="eco-tip-wrap"><span class="eco-tip-btn">ℹ</span>
                <div class="eco-tip-text"><strong>Emission Factor:</strong> 0.997 kg CO₂/kWh<br>Source: CEA India Grid Factor 2023<br><br><em>= Energy × 0.997 ÷ 1000</em></div>
            </div></div>""", unsafe_allow_html=True)
    with e2:
        st.markdown(f"""<div class="eco-card coal">
            <span class="eco-icon">🪨</span>
            <div class="eco-label">Coal Saved</div>
            <div class="eco-value">{coal:,.3f}<span class="eco-unit"> ton</span></div>
            <div class="eco-desc">{daily_kwh:,.0f} kWh × 0.404 kg/kWh</div>
            <div class="eco-tip-wrap"><span class="eco-tip-btn">ℹ</span>
                <div class="eco-tip-text"><strong>Coal Equivalent:</strong> 0.404 kg/kWh<br>Std. calorific value ~3500 kcal/kg<br><br><em>= Energy × 0.404 ÷ 1000</em></div>
            </div></div>""", unsafe_allow_html=True)
    with e3:
        st.markdown(f"""<div class="eco-card tree">
            <span class="eco-icon">🌳</span>
            <div class="eco-label">Equivalent Trees</div>
            <div class="eco-value">{tree:,.1f}<span class="eco-unit"> trees</span></div>
            <div class="eco-desc">{daily_kwh:,.0f} kWh × 0.054 trees/kWh</div>
            <div class="eco-tip-wrap"><span class="eco-tip-btn">ℹ</span>
                <div class="eco-tip-text"><strong>Tree Absorption:</strong> 0.054 trees/kWh<br>1 mature tree ≈ 18.5 kg CO₂/year<br>(IPCC / EPA estimate)<br><br><em>= Energy × 0.054</em></div>
            </div></div>""", unsafe_allow_html=True)


